1	"use client";
2	
3	import * as React from "react";
4	import { useTransition } from "react";
5	import { Check, X, Ban } from "lucide-react";
6	import { Card } from "@/components/ui/Card";
7	import { Button } from "@/components/ui/Button";
8	import { Tag } from "@/components/ui/Tag";
9	import { Avatar } from "@/components/ui/Avatar";
10	import { VoicePlayer } from "@/components/ui/VoicePlayer";
11	import { decideProvider } from "@/app/(admin)/admin/actions";
12	import { formatBlockPrice, formatRating } from "@/lib/format";
13	import { t } from "@/lib/i18n";
14	import { useToast } from "@/components/ui/Toast";
15	import { type ProviderRow } from "@/lib/supabase/types";
16	
17	type Decision = "approve" | "reject" | "suspend";
18	
19	const STATUS_LABEL: Record<ProviderRow["status"], string> = {
20	  approved: t("admin.statusApproved"),
21	  pending: t("admin.statusPending"),
22	  rejected: t("admin.statusRejected"),
23	  suspended: t("admin.statusSuspended"),
24	};
25	
26	export function ProviderApprovalCard({
27	  provider,
28	  audioUrl,
29	}: {
30	  provider: ProviderRow;
31	  audioUrl: string | null;
32	}) {
33	  const [pending, startTransition] = useTransition();
34	  const { announce, toast } = useToast();
35	
36	  function decide(decision: Decision) {
37	    startTransition(async () => {
38	      const res = await decideProvider({ providerId: provider.id, decision });
39	      if (!res.ok) {
40	        toast(t("admin.decisionError"), "alert");
41	        return;
42	      }
43	      const key =
44	        decision === "approve"
45	          ? "admin.approvedAnnounce"
46	          : decision === "reject"
47	            ? "admin.rejectedAnnounce"
48	            : "admin.suspendedAnnounce";
49	      announce(t(key, { name: provider.display_name }), true);
50	    });
51	  }
52	
53	  return (
54	    <Card as="li" className="flex flex-col gap-4">
55	      <div className="flex items-start gap-3">
56	        <Avatar name={provider.display_name} color={provider.avatar_color} />
57	        <div className="flex-1">
58	          <h3 className="text-h3">{provider.display_name}</h3>
59	          <p className="text-sm font-bold text-ink-soft">
60	            {STATUS_LABEL[provider.status]} ·{" "}
61	            {t("admin.bgCheckLabel")}: {provider.bg_check_status}
62	            {provider.rating_count > 0
63	              ? ` · ${formatRating(provider.rating_avg)} (${provider.rating_count})`
64	              : ""}
65	          </p>
66	        </div>
67	      </div>
68	
69	      <VoicePlayer name={provider.display_name} intro={provider.bio} big audioUrl={audioUrl} />
70	
71	      <dl className="flex flex-col gap-2 text-base">
72	        <div className="flex flex-wrap items-center gap-2">
73	          <dt className="font-bold text-ink-soft">{t("admin.topicsLabel")}:</dt>
74	          {provider.topics.map((topic) => (
75	            <dd key={topic}>
76	              <Tag>{topic}</Tag>
77	            </dd>
78	          ))}
79	        </div>
80	        <div className="flex flex-wrap items-center gap-2">
81	          <dt className="font-bold text-ink-soft">
82	            {t("admin.languagesLabel")}:
83	          </dt>
84	          <dd className="text-ink">{provider.languages.join(", ")}</dd>
85	        </div>
86	        <div className="flex flex-wrap items-center gap-3">
87	          <dt className="font-bold text-ink-soft">{t("admin.pricesLabel")}:</dt>
88	          <dd className="text-ink">
89	            {formatBlockPrice(provider.price_block_15_cents, 15)} ·{" "}
90	            {formatBlockPrice(provider.price_block_30_cents, 30)} ·{" "}
91	            {formatBlockPrice(provider.price_block_45_cents, 45)}
92	          </dd>
93	        </div>
94	      </dl>
95	
96	      <div className="flex flex-wrap gap-3 border-t border-border pt-4">
97	        {provider.status !== "approved" ? (
98	          <Button icon={Check} onClick={() => decide("approve")} disabled={pending}>
99	            {t("admin.approve")}
100	          </Button>
101	        ) : null}
102	        {provider.status !== "suspended" && provider.status !== "rejected" ? (
103	          <Button
104	            variant="ghost"
105	            icon={Ban}
106	            onClick={() => decide("suspend")}
107	            disabled={pending}
108	          >
109	            {t("admin.suspend")}
110	          </Button>
111	        ) : null}
112	        {provider.status === "pending" ? (
113	          <Button
114	            variant="danger"
115	            icon={X}
116	            onClick={() => decide("reject")}
117	            disabled={pending}
118	          >
119	            {t("admin.reject")}
120	          </Button>
121	        ) : null}
122	      </div>
123	    </Card>
124	  );
125	}
