1	import { describe, it, expect, vi } from "vitest";
2	import { screen } from "@testing-library/react";
3	import userEvent from "@testing-library/user-event";
4	import { axe } from "jest-axe";
5	import { renderWithProviders } from "./helpers";
6	
7	// Provider components import "use server" actions that pull in server-only
8	// modules; mock them so the components render in jsdom.
9	vi.mock("@/app/(provider)/provider/actions", () => ({
10	  completeOnboarding: vi.fn(async () => ({ ok: true })),
11	  setAvailability: vi.fn(async () => ({ ok: true })),
12	}));
13	vi.mock("next/navigation", () => ({
14	  useRouter: () => ({ push: vi.fn() }),
15	}));
16	
17	import { AvailabilityToggle } from "@/components/provider/AvailabilityToggle";
18	import { OnboardingFlow } from "@/components/provider/OnboardingFlow";
19	
20	const INITIAL = {
21	  displayName: "Nadia",
22	  bio: "",
23	  voiceIntroPath: null,
24	  languages: [],
25	  topics: [],
26	  price15: "",
27	  price30: "",
28	  price45: "",
29	  overage: "",
30	  isAvailableNow: false,
31	};
32	
33	describe("AvailabilityToggle", () => {
34	  it("exposes a switch with aria-checked and a text label (not colour alone)", async () => {
35	    const { container } = renderWithProviders(
36	      <AvailabilityToggle initial={false} />,
37	    );
38	    const sw = screen.getByRole("switch");
39	    expect(sw).toHaveAttribute("aria-checked", "false");
40	    expect(sw).toHaveTextContent(/you're offline/i);
41	    expect(await axe(container)).toHaveNoViolations();
42	  });
43	
44	  it("flips state on click", async () => {
45	    const user = userEvent.setup();
46	    renderWithProviders(<AvailabilityToggle initial={false} />);
47	    await user.click(screen.getByRole("switch"));
48	    expect(screen.getByRole("switch")).toHaveAttribute("aria-checked", "true");
49	  });
50	
51	  it("shows the locked message when not yet approved", () => {
52	    renderWithProviders(<AvailabilityToggle initial={false} disabled />);
53	    expect(screen.queryByRole("switch")).not.toBeInTheDocument();
54	    expect(screen.getByText(/once your profile is approved/i)).toBeInTheDocument();
55	  });
56	});
57	
58	describe("OnboardingFlow", () => {
59	  it("renders step 1 of 4 with labelled controls and no a11y violations", async () => {
60	    const { container } = renderWithProviders(
61	      <OnboardingFlow providerId="p1" initial={INITIAL} />,
62	    );
63	    expect(screen.getByText("Step 1 of 4")).toBeInTheDocument();
64	    expect(
65	      screen.getByRole("heading", { name: /record your voice intro/i }),
66	    ).toBeInTheDocument();
67	    expect(screen.getByText(/a short written intro/i)).toBeInTheDocument();
68	    expect(await axe(container)).toHaveNoViolations();
69	  });
70	
71	  it("advances to the topics step", async () => {
72	    const user = userEvent.setup();
73	    renderWithProviders(<OnboardingFlow providerId="p1" initial={INITIAL} />);
74	    await user.click(screen.getByRole("button", { name: /next/i }));
75	    expect(
76	      screen.getByRole("heading", { name: /what do you enjoy talking about/i }),
77	    ).toBeInTheDocument();
78	  });
79	});
